-- 074: L10 — legal content as data + site-wide settings
--
-- Moves /terms, /privacy, /accessibility page bodies out of static
-- .tsx files and into `legal_documents`. History is captured on every
-- edit so we can answer "what did the user see the day they signed
-- up". Settings covers the values that repeat across pages (company
-- name, accessibility coordinator, support email) so a single edit in
-- /admin/legal propagates everywhere without a redeploy.
--
-- Tables land in org_db (spec §1) — same DB the admin service already
-- reads/writes for other CRUD.
--
-- Seed strategy: three DRAFT rows with the L6 content already
-- migrated to markdown, so /legal/{slug} returns real launch-ready
-- copy on day 1. Admin edits then advance version + history.
-- All three keep is_draft=TRUE (except accessibility, whose statement
-- is already fully drafted per docs/accessibility_statement.md).

USE org_db;

CREATE TABLE IF NOT EXISTS legal_documents (
  slug          VARCHAR(32)  NOT NULL PRIMARY KEY,
  title_he      VARCHAR(200) NOT NULL,
  body_md       MEDIUMTEXT   NOT NULL,
  version       INT          NOT NULL DEFAULT 1,
  effective_at  DATE             NULL,
  is_draft      BOOLEAN      NOT NULL DEFAULT TRUE,
  updated_at    TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  updated_by    VARCHAR(64)      NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS legal_document_history (
  id           CHAR(36)     NOT NULL PRIMARY KEY,
  slug         VARCHAR(32)  NOT NULL,
  version      INT          NOT NULL,
  body_md      MEDIUMTEXT   NOT NULL,
  replaced_at  TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
  replaced_by  VARCHAR(64)      NULL,
  INDEX idx_legal_hist (slug, version)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS site_settings (
  setting_key  VARCHAR(64)  NOT NULL PRIMARY KEY,
  setting_val  VARCHAR(500)     NULL,
  label_he     VARCHAR(200) NOT NULL,
  updated_at   TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Seed: legal_documents — bodies are L6 content in markdown ────

INSERT INTO legal_documents (slug, title_he, body_md, is_draft, effective_at) VALUES

('terms', 'תנאי שימוש',
'## 1. מיהו נותן השירות\n\nפלטפורמת TagidAI מופעלת על ידי **Lead Agentic** (עוסק מורשה 032340283), רבי יוסף בוכריץ 6, ראשון לציון 7511404 (להלן: "הפלטפורמה").\n\n## 2. מהות השירות\n\nהפלטפורמה היא **שירות תיווך מידע** בין קבלנים בענף הבנייה לבין תאגידי כוח אדם המורשים להעסיק עובדים זרים. הפלטפורמה מאפשרת לתאגידים לפרסם מודעות זמינות עובדים ולקבלנים לחפש ולפנות ישירות לתאגיד.\n\n> **הפלטפורמה איננה צד לעסקה** בין הקבלן לתאגיד. איננו מעסיקים עובדים, איננו מספקים עובדים בעצמנו, איננו מבצעים תשלומים בין הצדדים ואיננו אחראים לביצוע ההסכם, לזמינות העובדים או לאיכות השירות. כל התקשרות, הסכם ותנאיו — נחתמים ומבוצעים ישירות בין הקבלן לתאגיד.\n\n## 3. כשירות להשתמש בשירות\n\nהשירות מיועד ל**משתמשים עסקיים בלבד** — בגירים המורשים לחייב את הארגון שאליו הם רשומים. המשתמש מצהיר כי הפרטים שמסר נכונים וכי הוא מוסמך לפעול בשם הישות שאליה הוא רשום.\n\n## 4. מנוי, ביטול והחזרים\n\n- לחלק מהמסלולים תקופת ניסיון ללא תשלום; פרטי המסלול מוצגים בדף החיוב.\n- המנוי מתחדש אוטומטית מדי חודש עד לביטול על ידי המשתמש.\n- ניתן לבטל את המנוי בכל עת דרך דף החיוב. הביטול נכנס לתוקף בתום התקופה שבעדה כבר שולם.\n- לא יינתן זיכוי חלקי על ימים לא מנוצלים בתקופה קיימת.\n\n## 5. חשיפות פרטי קשר\n\n- המסלול קובע מכסת חשיפות חודשית של פרטי קשר לתאגידים.\n- המכסה **אינה נצברת** — מכסה שלא נוצלה החודש אינה מועברת לחודש הבא.\n- חשיפה שנוצלה — נספרת, ולא ניתנת להחזרה, גם אם ההתקשרות בפועל לא יצאה לפועל.\n\n## 6. תוכן המשתמשים\n\nהמפרסם אחראי אישית לנכונות המידע במודעה שהעלה ולזכותו לפרסמו. אנו רשאים להסיר תוכן החורג מהתקנון, מהוראות הדין או מפוגע בזכויות צד שלישי.\n\n## 7. הגבלת אחריות\n\nהפלטפורמה מוצעת "כמות שהיא" (AS IS). איננו נותנים אחריות לדיוק המידע במודעות, לזמינות עובדים בפועל, להתאמת התאגיד או הקבלן לצרכי הצד השני, או לתוצאות התקשרות שנעשתה בעקבות שימוש בפלטפורמה. איננו אחראים לנזק ישיר או עקיף שנגרם כתוצאה מהשימוש בפלטפורמה.\n\n## 8. הפסקת השירות\n\nאנו רשאים להשעות או לסגור חשבון משתמש במקרים של הפרת התנאים, פרסום מטעה, פעילות בלתי חוקית או ניסיון לעקוף מגבלות טכניות של הפלטפורמה. במקרים מתאימים תישלח הודעה מקדימה.\n\n## 9. שינויים בתנאים\n\nאנו רשאים לעדכן את התנאים מעת לעת. שינויים מהותיים יובאו לידיעת המשתמש באמצעות התראה בפלטפורמה או בדוא"ל, ותאריך העדכון בראש עמוד זה יעודכן בהתאם.\n\n## 10. דין ושיפוט\n\nעל השימוש בשירות יחול הדין הישראלי בלבד. סמכות השיפוט הבלעדית בכל מחלוקת תהיה נתונה לבתי המשפט המוסמכים במחוז תל אביב-יפו.',
TRUE, '2026-09-12'),

('privacy', 'מדיניות פרטיות',
'## 1. מיהו האחראי על המידע\n\nהמידע נאסף ומעובד על ידי **Lead Agentic** (עוסק מורשה 032340283), רבי יוסף בוכריץ 6, ראשון לציון. פניות בנושא פרטיות — לדוא"ל [yulian@leadagentic.net](mailto:yulian@leadagentic.net).\n\n## 2. מה אנחנו אוספים בפועל\n\n- **מספר טלפון** — לזיהוי בכניסה (OTP).\n- **שם, דוא"ל, ח.פ** — בעת הרישום ולצורך שירות שוטף.\n- **מסמכים** — רישיונות, תעודות ואישורים שהעליתם.\n- **התאמה למרשם ממשלתי** — התאמת מספר עוסק ורישיון קבלן מול פנקסים ציבוריים (רשם הקבלנים; רשות האוכלוסין).\n- **שאילתות חיפוש** — הטקסט החופשי שהזנתם בחיפוש נשלח לספק AI חיצוני לצורך פירוש (ראו סעיף 3).\n- **הקלטות קול** — אם השתמשתם בחיפוש קולי, ההקלטה נשלחת לספק תמלול חיצוני (ראו סעיף 3).\n- **רשומות חשיפה** — מי חשף פרטי קשר של מי, ומתי (ראו סעיף 4).\n- **תשלומים** — פרטי כרטיס האשראי **אינם נשמרים אצלנו** — נשמר טוקן בלבד אצל ספק הסליקה.\n- **SMS / WhatsApp** — מספרי הטלפון שאיתם התכתבתם, לצורך שליחה של הודעות מערכת ותפעול.\n\n## 3. צדדים שלישיים\n\nלמען השקיפות, אלה הספקים שאיתם המידע שלכם עשוי להשתתף — בשמם המלא ולפי מטרת השימוש:\n\n- **Anthropic (Claude)** — פירוש הטקסט של שאילתות החיפוש שהזנתם. השירות פועל מחוץ לישראל.\n- **ElevenLabs** — תמלול הקלטות קול לחיפוש הקולי. השירות פועל מחוץ לישראל.\n- **Cardcom** — סליקת אשראי וטוקניזציה של אמצעי תשלום. פרטי הכרטיס עצמם מאוחסנים אצל Cardcom, לא אצלנו.\n- **Vonage** — שליחת SMS ו-WhatsApp.\n- **data.gov.il** — פנקס הקבלנים ורשם התאגידים לאימות מסמכי רישום.\n- **Railway / MySQL** — תשתית ענן ואחסון בסיס הנתונים של המערכת.\n\n## 4. רשומות חשיפה של פרטי קשר\n\nכאשר קבלן חושף את פרטי הקשר של תאגיד באמצעות הפלטפורמה, נשמרת רשומה של האירוע: זהות הקבלן, זהות התאגיד ומודעה, ותאריך החשיפה.\n\nהמידע הזה משמש אותנו לאכיפת מכסות המנוי, לתמיכה במקרים של מחלוקת ולסטטיסטיקות מוצר. **בנוסף, לתאגיד המפרסם מוצג מדד מספרי של החשיפות שהמודעה שלו קיבלה** — כלומר, לתאגיד יש נראות לכמה קבלנים התעניינו במודעה שלו, ולא רק לקבלן. איננו מציגים את זהותו של הקבלן לתאגיד אלא במסגרת עסקה שנסגרה בין השניים.\n\n## 5. מטרות ובסיס חוקי\n\n- **ביצוע החוזה** — הפעלת השירות שנרשמתם אליו: הצגת מודעות, חשיפת פרטי קשר, גבייה על מנוי.\n- **חובות חוקיות** — הנפקת חשבוניות, שמירת מסמכי חשבונאות, אימות מול מרשמים ממשלתיים.\n- **אינטרס לגיטימי** — מניעת שימוש לרעה, אבטחת מידע, שיפור השירות באמצעות דוחות שימוש מצטברים.\n- **הסכמה** — שליחת עדכונים שיווקיים (רק אם ניתנה הסכמה נפרדת).\n\n## 6. תקופת שמירה\n\nהמידע נשמר כל עוד החשבון פעיל, וכן לאחר סגירתו לפרק הזמן הנדרש לפי הדין. פרטי כרטיס לא נשמרים אצלנו כלל — רק אצל ספק הסליקה.\n\n## 7. הזכויות שלכם\n\nלכם יש זכות לפי חוק הגנת הפרטיות התשמ"א-1981 (ותיקון 13 שלו):\n\n- **עיון** — לבקש לראות איזה מידע נשמר עליכם.\n- **תיקון** — לבקש לתקן מידע לא מדויק.\n- **מחיקה** — לבקש למחוק מידע (בכפוף לחובות שמירה חוקיות).\n- **הגבלת עיבוד** — לבקש להגביל את השימוש במידע במקרים מסוימים.\n\nפנייה למימוש זכות תישלח לדוא"ל שצוין בסעיף 1 עם "פנייה בנושא פרטיות" בכותרת. נשיב תוך זמן סביר בהתאם לחוק.\n\n## 8. אבטחה\n\nאנו נוקטים אמצעים סבירים להגנה על המידע — הצפנת תעבורה (HTTPS), הגבלת גישה, אחסון מבודד לפי סוג נתון, וטוקניזציה של פרטי אשראי בצד ספק הסליקה. אין אבטחה מוחלטת; במקרה של אירוע אבטחה מהותי נפעל בהתאם להוראות הדין ונודיע לגורמים הרלוונטיים כנדרש.\n\n## 9. עוגיות\n\nהאתר משתמש ב**עוגיות חיוניות בלבד** — בעיקר לשמירת מצב התחברות (טוקן הזדהות ואסימון רענון). איננו מפעילים באתר כלי ניתוח מסחריים או פיקסלים שיווקיים של צדדים שלישיים, ולכן אין באנר הסכמה. אם ייעשה שינוי בעתיד — יופיע באנר הסכמה מתאים.\n\n## 10. שינויים במדיניות\n\nאנו רשאים לעדכן מדיניות זו מעת לעת. שינויים מהותיים יובאו לידיעתכם דרך הפלטפורמה או בדוא"ל. תאריך העדכון בראש העמוד יעודכן בהתאם.',
TRUE, '2026-09-12'),

('accessibility', 'הצהרת נגישות',
'## 1. המחויבות שלנו\n\nאנו רואים חשיבות רבה במתן שירות שוויוני לכלל הציבור, לרבות אנשים עם מוגבלות. אנו פועלים להנגשת האתר בהתאם ל**תקן הישראלי ת"י 5568** ולתקנות שוויון זכויות לאנשים עם מוגבלות (התאמות נגישות לשירות), התשע"ג-2013.\n\nהאתר נמצא בתהליך השלמת התאמות נגישות. בהצהרה זו מפורטות ההתאמות שכבר בוצעו, וכן דרכי הפנייה לקבלת סיוע או לדיווח על תקלה.\n\n## 2. התאמות שבוצעו\n\n### 2.1 ניווט והפעלה\n\n- ניתן להפעיל את רכיבי האתר באמצעות מקלדת.\n- חלונות קופצים כוללים ניהול מיקוד: המיקוד עובר לחלון בעת פתיחתו, נלכד בתוכו כל עוד הוא פתוח, וחוזר לנקודת המוצא בעת סגירתו.\n- ניתן לסגור חלונות קופצים באמצעות מקש Esc.\n\n### 2.2 תצוגה וקריאות\n\n- האתר בנוי בעברית עם תמיכה מלאה בכיווניות מימין לשמאל.\n- ניגודיות הצבעים ברכיבים המרכזיים נבדקה ועומדת ברמה AA.\n- מידע אינו מועבר באמצעות צבע בלבד; סימונים ותגיות כוללים טקסט.\n- האתר מכבד את העדפת המערכת להפחתת אנימציות.\n\n### 2.3 טפסים והודעות\n\n- שדות הטופס כוללים תוויות מפורשות.\n- שדה קוד האימות החד-פעמי תומך במילוי אוטומטי בהתקנים נתמכים.\n- הודעות שגיאה מנוסחות בעברית ומסבירות מה קרה וכיצד להמשיך.\n- שינויי מצב בתהליך החיפוש — טעינה, מספר תוצאות, שגיאה — מוכרזים לטכנולוגיות מסייעות.\n\n### 2.4 מבנה\n\n- שימוש במבנה סמנטי ובכותרות היררכיות.\n- לרכיבים אינטראקטיביים שמות נגישים.\n\n## 3. התאמות שטרם הושלמו\n\nאנו ממשיכים לבדוק ולתקן. נכון למועד עדכון הצהרה זו טרם הושלמה סקירת נגישות מקיפה של כלל מסכי האתר.\n\n**אם נתקלתם בקושי — נשמח שתפנו אלינו, ונפעל לתקן.**\n\n## 4. דיווח על בעיית נגישות\n\nנתקלתם בבעיה? נשמח לשמוע. כדי שנוכל לטפל במהירות, ציינו:\n\n- **כתובת העמוד** שבו נתקלתם בקושי.\n- **תיאור קצר של הבעיה** ומה ניסיתם לעשות.\n- **הדפדפן והמכשיר** שבהם השתמשתם, ואם רלוונטי — טכנולוגיה מסייעת.\n\nנטפל בפנייה ונשיב בהקדם, ובכל מקרה **בתוך 60 ימים** בהתאם לתקנות.',
FALSE, '2026-09-12')

ON DUPLICATE KEY UPDATE slug=slug;

